<script lang="ts">import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import ProjectCard from '$lib/components/ProjectCard.svelte';import {workspace} from '$lib/stores/workspace';let query='';$: filtered=$workspace.projects.filter(p=>[p.name,p.repo,p.framework,...$workspace.domains.filter(d=>d.project===p.id).map(d=>d.name)].join(' ').toLowerCase().includes(query.trim().toLowerCase()));</script><Heading title="Projects" subtitle="Create and manage websites, APIs and applications."><a class="btn primary" href="/projects/new"><Icon name="Plus"/> New project</a></Heading><div class="toolbar project-directory-toolbar"><label class="search"><Icon name="Search"/><input aria-label="Search projects" placeholder="Search projects…" bind:value={query}/></label></div><div class="project-gallery-count" aria-live="polite">{filtered.length===$workspace.projects.length?filtered.length:filtered.length+' of '+$workspace.projects.length} {filtered.length===1?'project':'projects'}</div>{#if filtered.length}<section class="project-gallery gallery14" aria-label="Projects">{#each filtered as p (p.id)}<ProjectCard project={p} domains={$workspace.domains}/>{/each}</section>{:else}<section class="card empty-state"><h3>No matching projects</h3><p>Try another name or website address.</p></section>{/if}
